import {useMemo,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {GuestVisits} from '../../src/hearthside/GuestVisits.tsx';
import {GuestRoomView} from '../../src/hearthside/GuestRoomView.tsx';
import {newKittyPiece} from '../../src/core/kittyStudio.ts';
import type {GuestTheme,GuestRoomKind,GuestArrangement} from '../../src/hearthside/guestContracts.ts';
const piece=newKittyPiece('synthetic','2026-09-12T00:00:00.000Z');
const objects:GuestArrangement['objects']=[{id:'preview-note',kind:'note',text:'You are welcome here.',x:.23,y:.32},{id:'preview-piece',kind:'piece',displaySize:'standard',appearance:{sculpt:piece.sculpt,paint:piece.paint},x:.55,y:.7},{id:'preview-memory',kind:'memory',title:'An afternoon together',captions:[{label:'Voice 1',text:'I remember your laugh.'},{label:'Voice 2',text:'I remember the light.'}],media:[],pieces:[],x:.76,y:.34}];
function Proof(){const [actor,setActor]=useState('alice'),[theme,setTheme]=useState<GuestTheme>('classic'),[room,setRoom]=useState<GuestRoomKind>('common'),[preview,setPreview]=useState(false),[closed,setClosed]=useState(false);const auth=useMemo(()=>({scopeKey:'local-guest-proof/'+actor,token:async()=>actor+'.synthetic.jwt'}),[actor]),host=useMemo(()=>['alice','bob'].includes(actor)?{householdId:'HH-FIRST',choices:[{kind:'experience' as const,id:'experience-1',revision:1,label:'A day by the water'},{kind:'piece' as const,id:'piece-1',designId:'design-1',revision:1,label:'Our painted cat'},{kind:'memory' as const,id:'memory-1',revision:1,label:'An afternoon together'}]}:undefined,[actor]);return <><aside style={{padding:12,background:'#fff',font:'14px system-ui',display:'flex',gap:15,flexWrap:'wrap'}} aria-label="Local synthetic proof controls"><strong>Local synthetic guest proof</strong><label>Test participant <select value={actor} onChange={e=>{setActor(e.target.value);setClosed(false);}}>{['alice','bob','cara','dan'].map(a=><option key={a}>{a}</option>)}</select></label><label>Test theme <select value={theme} onChange={e=>setTheme(e.target.value as GuestTheme)}>{['classic','taylor','newfoundland'].map(t=><option key={t}>{t}</option>)}</select></label><label>Test room <select value={room} onChange={e=>setRoom(e.target.value as GuestRoomKind)}>{['common','studio','conservatory','theatre'].map(t=><option key={t}>{t}</option>)}</select></label><label><input type="checkbox" checked={preview} onChange={e=>setPreview(e.target.checked)}/> Isolated room matrix</label></aside>{preview?<main className="guest-visits" data-guest-theme={theme}><h1>A room prepared for a visit</h1><GuestRoomView arrangement={{version:1,title:'Synthetic guest room',welcome:'A small place to pause together.',theme,room,mode:'anytime',objects}}/></main>:closed?<button onClick={()=>setClosed(false)}>Open guest visits</button>:<GuestVisits auth={auth} theme={theme} host={host} onClose={()=>setClosed(true)}/>}</>;}createRoot(document.getElementById('root')!).render(<Proof/>);
